import * as THREE from 'three';
// Panel facade: one extruded slab with real window holes (the extrude walls are the reveal), glazing set back >= 0.1 m, seams, plinth.
export function makePanelFacade(w = 12, h = 15, floors = 5, bays = 4, rng = Math.random) {
  const g = new THREE.Group(); g.userData = { tag: 'facade', variant: [w, h, floors, bays].join('x') };
  const recess = 0.12;                                                   // >= 0.1 m glazing inset (5 cm is the floor; 10 cm scored)
  const shape = new THREE.Shape([[-w / 2, 0], [w / 2, 0], [w / 2, h], [-w / 2, h]].map(([x, y]) => new THREE.Vector2(x, y)));
  const windows = [];
  for (let f = 0; f < floors; f++) for (let b = 0; b < bays; b++) {
    const cx = -w / 2 + (w / bays) * (b + 0.5), cy = (h / floors) * (f + 0.55);
    if (![cx, cy].every(Number.isFinite)) continue;                       // NaN into Shape/Extrude crashes the build turn
    const hole = new THREE.Path(); hole.moveTo(cx - 0.75, cy - 0.7); hole.lineTo(cx + 0.75, cy - 0.7); hole.lineTo(cx + 0.75, cy + 0.7); hole.lineTo(cx - 0.75, cy + 0.7); hole.closePath();
    shape.holes.push(hole); windows.push([cx, cy]);
  }
  const l = 0.55 + (rng() - 0.5) * 0.1;                                   // per-building value jitter so rows do not repeat
  const wall = new THREE.Mesh(new THREE.ExtrudeGeometry(shape, { depth: 0.4, bevelEnabled: false }),
    new THREE.MeshStandardMaterial({ color: new THREE.Color().setHSL(0.09, 0.08, l), roughness: 0.9 }));
  wall.position.z = -0.4; wall.userData.tag = 'wall'; g.add(wall);        // front face at z = 0
  const litMat = new THREE.MeshStandardMaterial({ color: 0x0b1018, roughness: 0.2, emissive: 0x3a2e14, emissiveIntensity: 0.5 });
  const darkMat = new THREE.MeshStandardMaterial({ color: 0x0b0e12, roughness: 0.6 });
  for (const [cx, cy] of windows) {
    const win = new THREE.Group(); win.userData = { tag: 'window', recess };
    const glass = new THREE.Mesh(new THREE.PlaneGeometry(1.5, 1.4), rng() < 0.35 ? litMat : darkMat);
    glass.position.set(cx, cy, -recess); glass.userData.tag = 'glazing'; win.add(glass); g.add(win);
  }
  const seamMat = new THREE.MeshStandardMaterial({ color: 0x2a2624, roughness: 1 });
  for (let f = 1; f < floors; f++) { const s = new THREE.Mesh(new THREE.BoxGeometry(w + 0.02, 0.06, 0.04), seamMat); s.position.set(0, (h / floors) * f, 0.01); s.userData.tag = 'seam'; g.add(s); }
  for (let b = 1; b < bays; b++) { const s = new THREE.Mesh(new THREE.BoxGeometry(0.06, h, 0.04), seamMat); s.position.set(-w / 2 + (w / bays) * b, h / 2, 0.01); s.userData.tag = 'seam'; g.add(s); }
  const plinth = new THREE.Mesh(new THREE.BoxGeometry(w + 0.1, 0.8, 0.5), new THREE.MeshStandardMaterial({ color: 0x2f2b28, roughness: 1 }));
  plinth.position.set(0, 0.4, 0.03); plinth.userData.tag = 'plinth'; g.add(plinth);
  return g;
}
// Row rule: draw (w, h, floors, bays) per building from the seeded rng so no two neighbours match; break any 4+ identical bays with a stair tower or gap.
